#include <cstdio>
#include <cstddef>

#pragma pack(push, 1)          // 关闭填充：成员紧挨着排
struct WireMsg { char type; int len; double value; };
#pragma pack(pop)              // 恢复默认对齐

struct NativeMsg { char type; int len; double value; };

int main() {
    printf("packed sizeof=%zu native sizeof=%zu\n",
           sizeof(WireMsg), sizeof(NativeMsg));
    printf("packed offsets type=%zu len=%zu value=%zu\n",
           offsetof(WireMsg, type), offsetof(WireMsg, len), offsetof(WireMsg, value));
    printf("紧凑布局(1+4+8): %d\n", (int)(sizeof(WireMsg) == 13));
    // 注意：pack 用于按字节对齐的网络/磁盘协议；直接对 Packed 取成员地址可能未对齐
    return 0;
}
